messages.content:
Berikut manifest game **Kronologi 45: Jejak Proklamasi** — Endless Runner edukasi bertema kronologi peristiwa sekitar Proklamasi, dengan Sumpah Pemuda sebagai jebakan miskonsepsi utama.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "kronologi-45", title: "Kronologi 45: Jejak Proklamasi", seed: "kronologi-45-01",
  theme: { preset: "retro-pixel" },

  learning: {
    subject: "Sejarah Indonesia",
    concept: "Kronologi peristiwa sebelum, saat, dan sesudah Proklamasi 17 Agustus 1945",
    objectives: [
      "Mengelompokkan peristiwa sejarah berdasarkan urutan waktunya terhadap Proklamasi",
      "Membedakan peristiwa sebelum, saat, dan sesudah 17 Agustus 1945"
    ],
    misconceptions: [
      "Sumpah Pemuda terjadi setelah proklamasi kemerdekaan"
    ],
    mode: "category",
    categories: [
      { id: "sebelum", label: "Sebelum Proklamasi", color: "#E0A526" },
      { id: "saat",    label: "Saat Proklamasi",    color: "#E5484D" },
      { id: "sesudah", label: "Sesudah Proklamasi", color: "#2F80ED" }
    ],
    items: [
      { id: "sumpah-pemuda",   label: "Sumpah Pemuda",          category: "sebelum", explain: "Ikrar 28 Oktober 1928, jauh sebelum proklamasi 1945." },
      { id: "rengasdengklok",  label: "Peristiwa Rengasdengklok", category: "sebelum", explain: "16 Agustus 1945, golongan muda mendesak Soekarno-Hatta." },
      { id: "bom-hiroshima",   label: "Bom Hiroshima",          category: "sebelum", explain: "6 Agustus 1945, memicu Jepang menyerah kepada Sekutu." },
      { id: "rumusan-teks",    label: "Perumusan teks proklamasi", category: "sebelum", explain: "Malam 16-17 Agustus 1945 di rumah Laksamana Maeda." },
      { id: "pembacaan-teks",  label: "Pembacaan teks proklamasi", category: "saat",  explain: "Dibacakan Soekarno di Pegangsaan Timur 56, 17 Agustus 1945." },
      { id: "pengibaran",      label: "Pengibaran bendera pusaka", category: "saat", explain: "Oleh Latief Hendraningrat dan Suhud pada 17 Agustus 1945." },
      { id: "sambutan",        label: "Sambutan Soekarno",      category: "saat",    explain: "Pidato singkat setelah pembacaan teks proklamasi." },
      { id: "sidang-ppki",     label: "Sidang PPKI",            category: "sesudah", explain: "18 Agustus 1945, mengesahkan UUD 1945 dan memilih presiden." },
      { id: "sebar-berita",    label: "Penyebaran berita proklamasi", category: "sesudah", explain: "Lewat radio dan kurir ke berbagai daerah setelah 17 Agustus." },
      { id: "surabaya",        label: "Pertempuran Surabaya",   category: "sesudah", explain: "10 November 1945, terjadi setelah proklamasi kemerdekaan." },
      { id: "uud-1945",        label: "Pengesahan UUD 1945",    category: "sesudah", explain: "Disahkan PPKI pada 18 Agustus 1945, sehari setelah proklamasi." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",  w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "drum",  w: 60, h: 40, weight: 2 },
      { type: "hazard", id: "puing", w: 80, h: 30, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game ini mengajak pemain mengurutkan peristiwa sejarah ke kategori Sebelum, Saat, dan Sesudah Proklamasi, dengan Sumpah Pemuda sebagai jebakan miskonsepsi utama. Asumsi penting: item "Pengesahan UUD 1945" dan "Sidang PPKI" sama-sama merujuk peristiwa 18 Agustus 1945 namun dibedakan sebagai dua item agar variasi item cukup.
